import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom LayerNorm CUDA kernel definition
layernorm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void layer_norm_kernel(
    const float* input, const float* gamma, const float* beta, float* output,
    int batch_size, int num_features, int dim1, int dim2, float epsilon) {

    const int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const int feature_size = num_features * dim1 * dim2;
    __shared__ float s_mean, s_inv_std;

    // First pass: compute mean and variance
    float sum = 0.0f;
    float sq_sum = 0.0f;

    for (int idx = threadIdx.x; idx < feature_size; idx += blockDim.x) {
        const float val = input[batch_idx * feature_size + idx];
        sum += val;
        sq_sum += val * val;
    }

    // Warp-level reduction
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
        sq_sum += __shfl_down_sync(0xffffffff, sq_sum, offset);
    }

    if (threadIdx.x == 0) {
        const float mean = sum / feature_size;
        const float variance = sq_sum / feature_size - mean * mean;
        s_mean = mean;
        s_inv_std = rsqrtf(variance + epsilon);
    }
    __syncthreads();

    // Second pass: normalize and apply affine transformation
    for (int idx = threadIdx.x; idx < feature_size; idx += blockDim.x) {
        const int f = idx / (dim1 * dim2);
        const int d1 = (idx % (dim1 * dim2)) / dim2;
        const int d2 = idx % dim2;

        const float val = input[batch_idx * feature_size + idx];
        const float normalized = (val - s_mean) * s_inv_std;
        output[batch_idx * feature_size + idx] = normalized * gamma[f * dim1 * dim2 + d1 * dim2 + d2] + beta[f * dim1 * dim2 + d1 * dim2 + d2];
    }
}

torch::Tensor layer_norm_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    float epsilon) {

    const auto batch_size = input.size(0);
    const auto num_features = input.size(1);
    const auto dim1 = input.size(2);
    const auto dim2 = input.size(3);

    auto output = torch::empty_like(input);

    const dim3 blocks(batch_size);
    const dim3 threads(128);  // Optimal for modern GPUs

    layer_norm_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_features,
        dim1,
        dim2,
        epsilon);

    return output;
}
"""

layernorm_cpp_source = "torch::Tensor layer_norm_cuda(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, float epsilon);"

# Compile the CUDA extension
layernorm_ext = load_inline(
    name='layernorm',
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_source,
    functions=['layer_norm_cuda'],
    verbose=True,
    extra_cflags=['-O3'],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, normalized_shape):
        super().__init__()
        self.normalized_shape = normalized_shape
        self.gamma = nn.Parameter(torch.ones(normalized_shape))
        self.beta = nn.Parameter(torch.zeros(normalized_shape))
        self.epsilon = 1e-5

    def forward(self, x):
        return layernorm_ext.layer_norm_cuda(x, self.gamma, self.beta, self.epsilon)
